    "Key": "Default",
    "ResourceKey": "Default",
    "Script": "DetailedNav = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=DetailedNav]");
        container.empty();

        const grid = $('<div class="docs-nav-grid docs-nav-scope-grid"></div>');
        container.append(grid);

        var query = "ContentManagement/Page?$filter=AppId eq " + session.app.Id + " and ParentId eq " + session.page.PageId + "&$expand=PageInfo,Pages($expand=PageInfo,Pages($expand=PageInfo))";
        await api.get(query).then(function (pages) {
            const visiblePages = (pages.value || [])
                .filter(page => page.ShowOnMenus)
                .sort((a, b) => (a.Order || 0) - (b.Order || 0));

            const columnCount = visiblePages.length === 4 ? 2 : Math.min(3, Math.max(1, visiblePages.length));
            grid.attr("data-columns", columnCount);
            for (const page of visiblePages) DetailedNav.createItem(page, grid);
        });
    },
    createItem: function (page, parentElement) {
        if (page.Path === null) page.Path = "";
        const href = '/' + page.Path;
        const card = $('<article class="docs-nav-card docs-nav-scope"></article>');
        const title = $('<h3 class="docs-nav-title"></h3>');
        const titleLink = $('<a></a>').attr('href', href).text(DetailedNav.titleOf(page));
        const description = $('<p class="docs-nav-description"></p>').text(DetailedNav.descriptionOf(page));
        const footer = $('<div class="docs-nav-footer"></div>');
        const actions = $('<div class="docs-nav-actions"></div>');
        const link = $('<a class="docs-nav-command"></a>')
            .attr('href', href)
            .attr('aria-label', '[resource_displayname[go]] ' + DetailedNav.titleOf(page));
        link.append($('<span class="docs-nav-command-name"></span>').text('[resource_displayname[go]]'));
        link.append($('<span class="docs-nav-command-call" aria-hidden="true">()</span>'));
        link.append($('<span class="docs-nav-command-arrow" aria-hidden="true">&rarr;</span>'));

        title.append(titleLink);
        actions.append(link);
        footer.append(actions);
        card.append(title, description, footer);
        parentElement.append(card);
    },
    titleOf: function (page) {
        const culture = $("html").attr("lang");
        for (const info of page.PageInfo) { if (info.CultureId === culture) return info.Title; }
        for (const info of page.PageInfo) { if (info.CultureId === "") return info.Title; }
        return "unknown";
    },
    descriptionOf: function (page) {
        const culture = $("html").attr("lang");
        for (const info of page.PageInfo) { if (info.CultureId === culture) return info.Description; }
        for (const info of page.PageInfo) { if (info.CultureId === "") return info.Description; }
        return "unknown";
    }
};",
