<section class="devtools-api" aria-label="API Tester">
  <header class="dt-intro"><h2>API Tester</h2><p>Compose an HTTP request, send it from your browser, and inspect the response.<br><span>Requests are sent by your browser. The target API must allow cross-origin requests, unless it is hosted on ccoder.co.uk.</span></p></header>
  <div class="dt-request-bar">
    <label class="dt-hidden" for="dt-method">Method</label><select id="dt-method" class="dt-control" name="method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option><option>HEAD</option><option>OPTIONS</option></select>
    <label class="dt-hidden" for="dt-url">Request URL</label><input id="dt-url" class="dt-url" name="url" type="url" spellcheck="false" placeholder="https://api.example.com/v1/resource" />
    <button class="dt-send" name="send" type="button">Send</button>
  </div>
  <div class="dt-workspace">
    <section class="dt-panel" aria-label="Request details">
      <div class="dt-panel-head"><h3>Request</h3><button class="dt-secondary" name="clear" type="button">Clear</button></div>
      <div class="dt-tabs" role="tablist"><button class="dt-tab is-active" data-tab="headers" type="button">Headers</button><button class="dt-tab" data-tab="body" type="button">Body</button></div>
      <div class="dt-tab-panel is-active" data-panel="headers"><div name="headerRows"></div><button class="dt-secondary dt-add-row" name="addHeader" type="button">+ Add header</button></div>
      <div class="dt-tab-panel" data-panel="body"><textarea class="dt-body" name="body" spellcheck="false" placeholder='{"name":"value"}'></textarea><div style="margin-top:8px"><button class="dt-secondary" name="formatJson" type="button">Format JSON</button></div></div>
    </section>
    <section class="dt-panel" aria-label="Response details">
      <div class="dt-panel-head"><h3>Response</h3><div class="dt-response-meta"><span class="dt-badge" name="status">Not sent</span><span class="dt-badge" name="time">—</span><span class="dt-badge" name="size">—</span></div></div>
      <pre class="dt-response dt-response-empty" name="response">Send a request to see the response.</pre>
      <details class="dt-response-headers"><summary>Response headers</summary><pre name="responseHeaders">No response headers yet.</pre></details>
    </section>
  </div>
</section>",
